public final class Account {
    public static final int MAX_BALANCE = 1_000_000;
    private int balance;
    // 创建账户，初始余额必须在[0,1000000]内；金额使用整数单位，不进行浮点计算。
    public Account(int initialBalance) {
        if (initialBalance < 0 || initialBalance > MAX_BALANCE)
            throw new IllegalArgumentException("invalid balance");
        balance = initialBalance;
    }
    // 查询当前余额，不改变账户状态。
    public int getBalance() { return balance; }
    // 存入正整数金额且不能超过余额上限；先检查再更新，失败时余额保持不变。
    public void deposit(int amount) {
        // 先做减法形式的上限比较，避免先相加造成整数溢出。
        if (amount <= 0 || amount > MAX_BALANCE - balance)
            throw new IllegalArgumentException("invalid deposit");
        balance += amount;
    }
    // 取出正整数金额；余额不足时抛出专门异常，检查通过后才扣款。
    public void withdraw(int amount) {
        if (amount <= 0) throw new IllegalArgumentException("invalid withdrawal");
        if (amount > balance) throw new InsufficientFundsException("insufficient funds");
        balance -= amount;
    }
}

public final class InstructionParser {
    // 工具类不需要创建对象；外部通过InstructionParser.parse直接调用。
    private InstructionParser() { }
    // 按ASCII空格拆分输入，转换三个约定词和int整数；空串返回空数组，null或非法片段抛出参数异常。
    public static int[] parse(String input) {
        if (input == null) throw new IllegalArgumentException("null input");
        var values = new ArrayList<Integer>();
        // 只把普通空格作为分隔符；保留的空片段在循环内跳过。
        for (String token : input.split(" ", -1)) {
            if (token.isEmpty()) continue;
            switch (token) {
                case "ZERO" -> values.add(0);
                case "INC" -> values.add(1);
                case "DEC" -> values.add(-1);
                default -> values.add(parseNumber(token));
            }
        }
        // 将Integer列表拆箱成int数组；断言检查数组内容，不检查对象身份。
        return values.stream().mapToInt(Integer::intValue).toArray();
    }
    // 仅供parse调用：检查可选正负号和ASCII数字，再转换为int；越界时统一抛出参数异常。
    private static int parseNumber(String token) {
        int start = (token.charAt(0) == '+' || token.charAt(0) == '-') ? 1 : 0;
        if (start == token.length()) throw new IllegalArgumentException("invalid token");
        for (int i = start; i < token.length(); i++) {
            char c = token.charAt(i);
            if (c < '0' || c > '9') throw new IllegalArgumentException("invalid token");
        }
        try { return Integer.parseInt(token); }
        catch (NumberFormatException e) { throw new IllegalArgumentException("out of int32 range"); }
    }
}

public final class InsufficientFundsException extends RuntimeException {
    // 创建余额不足异常，保存错误说明；它与非法金额的参数异常不同。
    public InsufficientFundsException(String message) { super(message); }
}

public final class Rectangle {
    private final int left, top, right, bottom;
    // 创建闭矩形：允许宽或高为零；左大于右、上大于下时抛出参数异常。
    public Rectangle(int left, int top, int right, int bottom) {
        if (left > right || top > bottom)
            throw new IllegalArgumentException("invalid rectangle");
        this.left = left;
        this.top = top;
        this.right = right;
        this.bottom = bottom;
    }
    // 读取左边界横坐标，不修改矩形。
    public int getLeft() { return left; }
    // 读取上边界纵坐标；本例纵坐标向下增大。
    public int getTop() { return top; }
    // 读取右边界横坐标，不修改矩形。
    public int getRight() { return right; }
    // 读取下边界纵坐标，不修改矩形。
    public int getBottom() { return bottom; }
    // 判断与另一个矩形是否相交；先排除四种完全分离情况，共享边或角也算相交。
    public boolean intersectsWith(Rectangle r) {
        return !(r.left > right || r.right < left || r.top > bottom || r.bottom < top);
    }
    // 返回固定格式的坐标字符串，例如[1,2,3,4]，不插入空格。
    @Override public String toString() {
        return String.format("[%d,%d,%d,%d]", left, top, right, bottom);
    }
}
